import { withSupabase } from '@supabase/server'

const ORIGINS = new Set(['https://opravao.cz', 'https://www.opravao.cz'])
const MAX_BODY_BYTES = 16 * 1024
const RATE_WINDOW_MS = 15 * 60 * 1000
const RATE_LIMIT = 8
const RATE_RETENTION_MS = 24 * 60 * 60 * 1000
const encoder = new TextEncoder()
const REPAIR_TYPES = new Set(["Autoservis","Instalatér","Elektrikář","Spotřebiče","Dveře a okna","Střecha","Hodinový manžel","Zedník a obkladač","Malíř a natěrač","Klempíř","Pokrývač a klempíř","Truhlář","Truhlář a podlahář","Topenář","Ploty a brány","Zámečník","Klimatizace a vzduchotechnika","Žaluzie a rolety","Sklenář","Podlahář","Sádrokartonář","Fasády a zateplení","Kominík","Opravy garážových vrat","Zahradník","Úklid a čištění","Výkopové práce","Bourací a demoliční práce","Stěhování a vyklízení","Počítače a internet","Opravy počítačů a Wi-Fi","Rizikové kácení","Stavební dozor","Geodet"])

function respond(status: number, body: Record<string, unknown>, origin = '') {
  const allowedOrigin = ORIGINS.has(origin) ? origin : 'null'
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      'Access-Control-Allow-Origin': allowedOrigin,
      'Access-Control-Allow-Methods': 'POST, OPTIONS',
      'Access-Control-Allow-Headers': 'content-type, accept, apikey',
      'Access-Control-Max-Age': '600',
      'Vary': 'Origin',
      'Content-Type': 'application/json; charset=utf-8',
      'Cache-Control': 'no-store',
    },
  })
}

async function readBodyLimited(req: Request) {
  const announced = Number(req.headers.get('content-length') || 0)
  if (Number.isFinite(announced) && announced > MAX_BODY_BYTES) throw new Error('body_too_large')
  if (!req.body) return ''
  const reader = req.body.getReader()
  const chunks: Uint8Array[] = []
  let total = 0
  while (true) {
    const { value, done } = await reader.read()
    if (done) break
    if (!value) continue
    total += value.byteLength
    if (total > MAX_BODY_BYTES) {
      try { await reader.cancel() } catch {}
      throw new Error('body_too_large')
    }
    chunks.push(value)
  }
  const merged = new Uint8Array(total)
  let offset = 0
  for (const chunk of chunks) {
    merged.set(chunk, offset)
    offset += chunk.byteLength
  }
  return new TextDecoder().decode(merged)
}

function cleanText(value: unknown, max: number) {
  return typeof value === 'string' ? value.trim().replace(/\s+/g, ' ').slice(0, max) : ''
}
function validEmail(value: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/u.test(value) && value.length <= 254
}
function cleanPhone(value: string) {
  const raw = value.trim()
  const prefix = raw.startsWith('+') ? '+' : ''
  const digits = raw.replace(/\D/g, '')
  return digits.length >= 9 && digits.length <= 15 ? prefix + digits : ''
}
function inferRegion(place: string) {
  const normalized = place.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
  const regions: Array<[string, string]> = [
    ['praha', 'Hlavní město Praha'], ['brno', 'Jihomoravský kraj'], ['ostrava', 'Moravskoslezský kraj'],
    ['plzen', 'Plzeňský kraj'], ['olomouc', 'Olomoucký kraj'], ['liberec', 'Liberecký kraj'],
    ['ceske budejovice', 'Jihočeský kraj'], ['hradec kralove', 'Královéhradecký kraj'],
    ['pardubice', 'Pardubický kraj'], ['zlin', 'Zlínský kraj'], ['jihlava', 'Kraj Vysočina'],
  ]
  return regions.find(([city]) => normalized.includes(city))?.[1] || ''
}

export default {
  fetch: withSupabase(
    { auth: 'none', cors: 'disabled' },
    async (req, ctx) => {
      const origin = req.headers.get('origin') || ''
      if (!ORIGINS.has(origin)) return respond(403, { error: 'origin_not_allowed' }, origin)
      if (req.method === 'OPTIONS') return respond(200, { ok: true }, origin)
      if (req.method !== 'POST') return respond(405, { error: 'method_not_allowed' }, origin)
      if (!(req.headers.get('content-type') || '').toLowerCase().startsWith('application/json')) {
        return respond(415, { error: 'json_required' }, origin)
      }

      let raw = ''
      try { raw = await readBodyLimited(req) }
      catch (error) {
        return respond(error instanceof Error && error.message === 'body_too_large' ? 413 : 400, { error: 'invalid_body' }, origin)
      }
      let input: any
      try { input = JSON.parse(raw) }
      catch { return respond(400, { error: 'invalid_json' }, origin) }
      if (!input || typeof input !== 'object' || input.source !== 'opravao.cz' || input.transportVersion !== 1 || !input.lead || typeof input.lead !== 'object') {
        return respond(422, { error: 'invalid_envelope' }, origin)
      }

      if (input.type === 'company_registration') {
        const registration = input.lead
        const ico = cleanText(registration.ico, 8)
        const company = cleanText(registration.company, 150)
        const address = cleanText(registration.address, 250)
        const contactName = cleanText(registration.name, 120)
        const email = cleanText(registration.email, 254).toLowerCase()
        const phone = cleanPhone(cleanText(registration.phone, 40))
        const region = cleanText(registration.region, 80)
        const specialization = cleanText(registration.specialization, 600)
        const note = cleanText(registration.note, 1000)
        const regions = new Set(['Praha', 'Hlavní město Praha', 'Středočeský kraj', 'Jihočeský kraj', 'Plzeňský kraj', 'Karlovarský kraj', 'Ústecký kraj', 'Liberecký kraj', 'Královéhradecký kraj', 'Pardubický kraj', 'Kraj Vysočina', 'Jihomoravský kraj', 'Olomoucký kraj', 'Zlínský kraj', 'Moravskoslezský kraj', 'Celá Česká republika'])
        if (!/^\d{8}$/.test(ico) || company.length < 2 || contactName.length < 2 || !validEmail(email) || !phone || !regions.has(region) || specialization.length < 2) {
          return respond(422, { error: 'invalid_registration' }, origin)
        }

        const rateSalt = Deno.env.get('PLOTAO_RATE_SALT')?.trim()
        if (!rateSalt || rateSalt.length < 32) return respond(503, { error: 'rate_limit_unavailable' }, origin)
        const addressKey = req.headers.get('cf-connecting-ip')?.trim() || req.headers.get('x-real-ip')?.trim() || ''
        const userAgent = (req.headers.get('user-agent') || 'unknown').slice(0, 300)
        const keys = new Set<string>()
        const digest = async (value: string) => {
          const result = await crypto.subtle.digest('SHA-256', encoder.encode(value))
          return [...new Uint8Array(result)].map((byte) => byte.toString(16).padStart(2, '0')).join('')
        }
        if (addressKey) keys.add(await digest(rateSalt + '\\nnetwork\\n' + addressKey + '\\n' + userAgent))
        keys.add(await digest(rateSalt + '\\nregistration\\n' + ico + '\\n' + email))
        const rateKeys = [...keys]
        const since = new Date(Date.now() - RATE_WINDOW_MS).toISOString()
        const counts = await Promise.all(rateKeys.map((key_hash) => ctx.supabaseAdmin
          .from('plotao_lead_rate_events')
          .select('id', { count: 'exact', head: true })
          .eq('key_hash', key_hash)
          .gte('created_at', since)))
        if (counts.some((item) => item.error)) return respond(503, { error: 'rate_limit_unavailable' }, origin)
        if (counts.some((item) => (item.count || 0) >= RATE_LIMIT)) return respond(429, { error: 'rate_limited' }, origin)
        const { error: rateError } = await ctx.supabaseAdmin.from('plotao_lead_rate_events').insert(rateKeys.map((key_hash) => ({ key_hash })))
        if (rateError) return respond(503, { error: 'rate_limit_unavailable' }, origin)

        const receivedAt = new Date().toISOString()
        const payload = {
          schemaVersion: 1,
          source: 'opravao.cz',
          sourceLabel: 'Opravao.cz',
          mode: 'partner',
          registrationType: 'company',
          ico,
          company,
          registeredAddress: address,
          contactName,
          phone,
          email,
          region,
          specialization,
          note,
          privacyAcknowledged: true,
          privacyAcknowledgedAt: receivedAt,
        }
        const summary = ['Registrace firmy: ' + company, 'IČO: ' + ico, 'Obory: ' + specialization, note ? 'Poznámka: ' + note : ''].filter(Boolean).join(' | ')
        const { data, error } = await ctx.supabaseAdmin.from('plotao_leads').insert({
          submitted_at: receivedAt,
          source: 'opravao.cz',
          mode: 'partner',
          name: company.slice(0, 120),
          phone,
          email,
          place: address,
          region,
          note: summary.slice(0, 4000),
          payload,
        }).select('id').single()
        if (error || !data?.id) {
          console.error('opravao company registration insert failed', error?.code || 'missing_id')
          return respond(500, { error: 'storage_failed' }, origin)
        }
        let partnerProfileCreated = false
        let partnerId: string | null = null
        try {
          const { data: existing } = await ctx.supabaseAdmin.from('opravao_partners').select('id').or('ico.eq.' + ico + ',email.eq.' + email).limit(1).maybeSingle()
          if (existing?.id) partnerId = String(existing.id)
          else {
            const repairTypes = [...new Set(specialization.split('|')
              .map(item => item.trim().replace(/^jiný:\s*/i, '').trim())
              .filter(item => item.length >= 2)
              .map(item => item.slice(0, 80)))].slice(0, 26)
            const { data: created, error: partnerError } = await ctx.supabaseAdmin.from('opravao_partners').insert({
              company_name: company, contact_name: contactName, email, phone, ico,
              registration_origin: 'self_registered', registration_lead_id: data.id, registered_by: null,
              regions: region === 'Celá Česká republika' ? ['Hlavní město Praha', 'Středočeský kraj', 'Jihočeský kraj', 'Plzeňský kraj', 'Karlovarský kraj', 'Ústecký kraj', 'Liberecký kraj', 'Královéhradecký kraj', 'Pardubický kraj', 'Kraj Vysočina', 'Jihomoravský kraj', 'Olomoucký kraj', 'Zlínský kraj', 'Moravskoslezský kraj'] : [region], repair_types: repairTypes, active: false, status: 'pending',
              price_per_lead: 149, billing_email: email,
              notes: 'Žádost z webového formuláře. Obor uvedený firmou: ' + specialization + (note ? ' | ' + note : '')
            }).select('id').single()
            if (partnerError) console.error('opravao partner profile insert failed', partnerError.code || 'unknown')
            else { partnerId = String(created.id); partnerProfileCreated = true }
          }
        } catch (partnerError) {
          console.error('opravao partner profile setup failed', partnerError instanceof Error ? partnerError.message : 'unknown')
        }
        const cutoff = new Date(Date.now() - RATE_RETENTION_MS).toISOString()
        ctx.supabaseAdmin.from('plotao_lead_rate_events').delete().lt('created_at', cutoff).then(({ error }) => {
          if (error) console.error('opravao rate cleanup failed', error.code || 'unknown')
        })
        let confirmationSent = false
        const resendKey = Deno.env.get('RESEND_API_KEY')?.trim()
        if (!resendKey) {
          console.error('opravao company confirmation unavailable: RESEND_API_KEY missing')
        } else {
          const message = 'Potvrzení přijetí žádosti o registraci firmy – Opravao.cz'
          const bannerBase64 = ''
          const html = '<div style="max-width:800px;margin:0 auto"><img src="cid:opravao-company-confirmation" alt="Opravao.cz: Dobrý den, děkujeme za zájem o registraci firmy. Vaši žádost jsme přijali. Tým Opravao.cz." width="1200" style="display:block;width:100%;height:auto;border:0"></div>'
          try {
            const mailResponse = await fetch('https://api.resend.com/emails', {
              method: 'POST',
              headers: {
                'Authorization': 'Bearer ' + resendKey,
                'Content-Type': 'application/json',
                'Idempotency-Key': 'opravao-company-confirmation-' + data.id,
              },
              body: JSON.stringify({
                from: 'Opravao.cz <odpovedi@opravao.cz>',
                to: [email],
                reply_to: 'info@opravao.cz',
                subject: 'Potvrzení přijetí žádosti o registraci – Opravao.cz',
                text: message,
                html,
                attachments: [{
                  filename: 'opravao-potvrzeni-registrace.jpg',
                  content: bannerBase64,
                  content_type: 'image/jpeg',
                  content_id: 'opravao-company-confirmation',
                }],
              }),
            })
            let mailData: Record<string, unknown> = {}
            try { mailData = await mailResponse.json() } catch {}
            if (mailResponse.ok) {
              confirmationSent = true
              const { error: communicationError } = await ctx.supabaseAdmin.from('plotao_leads').update({
                communication: [{
                  direction: 'out',
                  channel: 'email',
                  body: message,
                  sent_at: new Date().toISOString(),
                  provider: 'resend',
                  provider_id: typeof mailData.id === 'string' ? mailData.id : null,
                  kind: 'company_registration_confirmation',
                }],
              }).eq('id', data.id).eq('source', 'opravao.cz')
              if (communicationError) console.error('opravao company confirmation log failed', communicationError.code || 'unknown')
            } else {
              console.error('opravao company confirmation rejected', mailResponse.status, typeof mailData.name === 'string' ? mailData.name : '')
            }
          } catch (error) {
            console.error('opravao company confirmation network failure', error instanceof Error ? error.message : 'unknown')
          }
        }
        return respond(201, { ok: true, type: 'company_registration', received_at: receivedAt, confirmation_sent: confirmationSent, partner_profile_created: partnerProfileCreated, partner_id: partnerId }, origin)
      }

      const rawLead = input.lead
      const repairType = cleanText(rawLead.repairType, 80)
      const place = cleanText(rawLead.place, 200)
      const rawLocation = rawLead.location && typeof rawLead.location === 'object' ? rawLead.location : null
      const lat = Number(rawLocation?.lat), lon = Number(rawLocation?.lon)
      const validRegions = new Set(['Hlavní město Praha','Středočeský kraj','Jihočeský kraj','Plzeňský kraj','Karlovarský kraj','Ústecký kraj','Liberecký kraj','Královéhradecký kraj','Pardubický kraj','Kraj Vysočina','Jihomoravský kraj','Olomoucký kraj','Zlínský kraj','Moravskoslezský kraj'])
      const geocodedRegion = cleanText(rawLocation?.region, 80)
      const locationData = rawLocation?.source === 'address' && cleanText(rawLocation?.label, 200) === place && Number.isFinite(lat) && Number.isFinite(lon) && lat >= 48.4 && lat <= 51.2 && lon >= 12 && lon <= 19 ? { lat, lon, label: place, source: 'address', region: validRegions.has(geocodedRegion) ? geocodedRegion : inferRegion(place) } : null
      const resolvedRegion = locationData?.region || inferRegion(place)
      const couponRegions = new Set(['Hlavní město Praha','Středočeský kraj','Jihočeský kraj','Plzeňský kraj','Karlovarský kraj','Ústecký kraj','Liberecký kraj','Královéhradecký kraj','Pardubický kraj','Kraj Vysočina','Jihomoravský kraj','Olomoucký kraj','Zlínský kraj','Moravskoslezský kraj'])
      const marketingConsent = rawLead.marketingConsent === true
      const marketingRegion = cleanText(rawLead.marketingRegion, 80)
      if (marketingConsent && (!couponRegions.has(marketingRegion) || !validEmail(cleanText(rawLead.email,254).toLowerCase()))) return respond(422, { error: 'invalid_marketing_consent' }, origin)
      const contact = cleanText(rawLead.contact, 254)
      const separateEmail = cleanText(rawLead.email, 254).toLowerCase()
      let email = ''
      let phone = ''
      if (contact.includes('@')) {
        email = contact.toLowerCase()
        if (!validEmail(email)) return respond(422, { error: 'invalid_contact' }, origin)
      } else {
        phone = cleanPhone(contact)
        if (!phone) return respond(422, { error: 'invalid_contact' }, origin)
        if (separateEmail) {
          if (!validEmail(separateEmail)) return respond(422, { error: 'invalid_contact' }, origin)
          email = separateEmail
        }
      }
      if (!REPAIR_TYPES.has(repairType)) return respond(422, { error: 'invalid_repair_type' }, origin)
      if (place.length < 2) return respond(422, { error: 'invalid_place' }, origin)

      const rateSalt = Deno.env.get('PLOTAO_RATE_SALT')?.trim()
      if (!rateSalt || rateSalt.length < 32) return respond(503, { error: 'rate_limit_unavailable' }, origin)
      const address = req.headers.get('cf-connecting-ip')?.trim() || req.headers.get('x-real-ip')?.trim() || ''
      const userAgent = (req.headers.get('user-agent') || 'unknown').slice(0, 300)
      const keys = new Set<string>()
      const digest = async (value: string) => {
        const result = await crypto.subtle.digest('SHA-256', encoder.encode(value))
        return [...new Uint8Array(result)].map((byte) => byte.toString(16).padStart(2, '0')).join('')
      }
      if (address) keys.add(await digest(rateSalt + '\nnetwork\n' + address + '\n' + userAgent))
      keys.add(await digest(rateSalt + '\ncontact\n' + phone + '\n' + email))
      const rateKeys = [...keys]
      const since = new Date(Date.now() - RATE_WINDOW_MS).toISOString()
      const counts = await Promise.all(rateKeys.map((key_hash) => ctx.supabaseAdmin
        .from('plotao_lead_rate_events')
        .select('id', { count: 'exact', head: true })
        .eq('key_hash', key_hash)
        .gte('created_at', since)))
      if (counts.some((item) => item.error)) return respond(503, { error: 'rate_limit_unavailable' }, origin)
      if (counts.some((item) => (item.count || 0) >= RATE_LIMIT)) return respond(429, { error: 'rate_limited' }, origin)
      const { error: rateError } = await ctx.supabaseAdmin
        .from('plotao_lead_rate_events')
        .insert(rateKeys.map((key_hash) => ({ key_hash })))
      if (rateError) return respond(503, { error: 'rate_limit_unavailable' }, origin)

      const receivedAt = new Date().toISOString()
      const name = 'Poptávka z Opravao.cz'
      const note = 'Typ opravy: ' + repairType
      const { data, error } = await ctx.supabaseAdmin
        .from('plotao_leads')
        .insert({
          submitted_at: receivedAt,
          source: 'opravao.cz',
          mode: 'help',
          name,
          phone,
          email,
          place,
          region: inferRegion(place),
          note,
          payload: {
            schemaVersion: 1,
            source: 'opravao.cz',
            sourceLabel: 'Opravao.cz',
            mode: 'help',
            repairType,
            name,
            phone,
            email,
            place,
            region: resolvedRegion,
            location: locationData,
            locationStatus: locationData ? 'matched' : 'needs_verification',
            note,
            marketingConsent,
            marketingRegion: marketingConsent ? marketingRegion : '',
            marketingConsentAt: marketingConsent ? receivedAt : null,
          },
        })
        .select('id')
        .single()
      if (error || !data?.id) {
        console.error('opravao lead insert failed', error?.code || 'missing_id')
        return respond(500, { error: 'storage_failed' }, origin)
      }

      const region = resolvedRegion
      let offersCreated = 0
      let offerEmailsSent = 0
      let distributionStatus = 'no_match'
      try {
        const normalize = (value: string) => value.normalize('NFD').replace(/[\\u0300-\\u036f]/g, '').toLowerCase().trim()
        const placeNorm = normalize(place)
        const regionAliases: Record<string,string> = {
          'praha':'Hlavní město Praha','hlavni mesto praha':'Hlavní město Praha',
          'brno':'Jihomoravský kraj','zlin':'Zlínský kraj','zlín':'Zlínský kraj',
          'ostrava':'Moravskoslezský kraj','plzen':'Plzeňský kraj'
        }
        const matchedRegion = region || Object.entries(regionAliases).find(([alias]) => placeNorm.includes(alias))?.[1] || ''
        const typeNorm = normalize(repairType)
        const typeAliases: Record<string,string[]> = {
          'instalater':['instalat','voda','vodovod','odpady'],'elektrikar':['elektr'],
          'spotrebice':['spotrebic','prack','myck'],'dvere a okna':['dvere','okna'],
          'strecha':['strech','pokryvac','klempir'],'hodinovy manzel':['hodinovy','manzel','drobne opravy'],
          'zednik a obkladac':['zedn','obklad','dlazb'],'malir a natěrač':['malir','natir'],
          'pokryvac a klempir':['pokryvac','klempir','strech'],'truhlar a podlahar':['truhlar','podlah'],
          'topenar':['topen','kotl'],'ploty a brany':['plot','brana','oploc','montaz oploceni']
        }
        const keywords = Object.entries(typeAliases).find(([key]) => typeNorm.includes(key))?.[1] || [typeNorm]
        const { data: candidates, error: matchError } = await ctx.supabaseAdmin.from('opravao_partners')
          .select('id,company_name,email,regions,repair_types,price_per_lead')
          .eq('status','approved').eq('active',true).limit(200)
        if (matchError) throw matchError
        const matched = (candidates || []).filter((p: any) => {
          const regions = Array.isArray(p.regions) ? p.regions : []
          const types = Array.isArray(p.repair_types) ? p.repair_types : []
          const regionMatch = !!matchedRegion && regions.some((r: string) => normalize(r) === normalize(matchedRegion) || (normalize(r)==='praha' && matchedRegion==='Hlavní město Praha') || normalize(r)==='cela ceska republika')
          const repairMatch = types.some((t: string) => {
            const n=normalize(t)
            return keywords.some(k => n.includes(k) || k.includes(n))
          })
          return regionMatch && repairMatch && typeof p.email==='string' && validEmail(p.email)
        }).slice(0,3)
        const resendKey = Deno.env.get('RESEND_API_KEY')?.trim()
        for (const partner of matched) {
          const { data: existingOffer } = await ctx.supabaseAdmin.from('opravao_lead_distribution').select('id').eq('lead_id',data.id).eq('partner_id',partner.id).maybeSingle()
          if (existingOffer?.id) continue
          const { data: offer, error: offerError } = await ctx.supabaseAdmin.from('opravao_lead_distribution').insert({
            lead_id:data.id, partner_id:partner.id, status:'offered', price:partner.price_per_lead || 149,
            offered_at:new Date().toISOString(),
            note:'Automatická nabídka; kontaktní údaje zákazníka nebyly předány.'
          }).select('id').single()
          if (offerError || !offer?.id) { console.error('opravao offer insert failed', offerError?.code || 'unknown'); continue }
          offersCreated++; distributionStatus='offered'
          if (!resendKey) continue
          const ref=String(data.id)
          const subject='Nová poptávka Opravao.cz – '+repairType
          const textBody='Dobrý den,\\n\\nna Opravao.cz je nová poptávka ve vašem oboru a kraji.\\nObor: '+repairType+'\\nLokalita: '+place+'\\nKraj: '+(matchedRegion||'bude upřesněn')+'\\nReference: '+ref+'\\nOdměna za přijatou poptávku: '+(partner.price_per_lead||149)+' Kč.\\n\\nZákaznické kontaktní údaje zatím nepředáváme. Pokud máte zájem, odpovězte na tento e-mail s referencí; předání kontaktu domluvíme se zákazníkem.\\n\\nTým Opravao.cz'
          try {
            const response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{'Authorization':'Bearer '+resendKey,'Content-Type':'application/json','Idempotency-Key':'opravao-provider-offer-'+offer.id},body:JSON.stringify({from:'Opravao.cz <odpovedi@opravao.cz>',to:[partner.email],reply_to:'info@opravao.cz',subject,text:textBody})})
            if(response.ok){offerEmailsSent++; await ctx.supabaseAdmin.from('opravao_lead_distribution').update({note:'Automatická nabídka odeslána e-mailem; kontaktní údaje zákazníka nebyly předány.'}).eq('id',offer.id)}
            else {const {error:expireError}=await ctx.supabaseAdmin.from('opravao_lead_distribution').update({status:'expired',note:'E-mailová nabídka se nepodařila odeslat.'}).eq('id',offer.id); if(expireError) console.error('opravao offer rollback failed',expireError.code||'unknown')}
          } catch (mailError) {
            console.error('opravao provider email network failure',mailError instanceof Error?mailError.message:'unknown')
            await ctx.supabaseAdmin.from('opravao_lead_distribution').update({status:'expired',note:'E-mailová nabídka se nepodařila odeslat.'}).eq('id',offer.id)
          }
        }
        if (matched.length && offerEmailsSent===0 && offersCreated===0) distributionStatus='no_match'
        else if (offerEmailsSent>0) distributionStatus='sent'
        else if (offersCreated>0) distributionStatus='email_unavailable'
      } catch (distributionError) {
        console.error('opravao automatic distribution failed',distributionError instanceof Error?distributionError.message:'unknown')
        distributionStatus='failed'
      }
      const cutoff = new Date(Date.now() - RATE_RETENTION_MS).toISOString()
      ctx.supabaseAdmin.from('plotao_lead_rate_events').delete().lt('created_at', cutoff).then(({ error }) => {
        if (error) console.error('opravao rate cleanup failed', error.code || 'unknown')
      })

      let confirmationSent = false
      const resendKey = Deno.env.get('RESEND_API_KEY')?.trim()
      if (!resendKey) {
        console.error('opravao customer confirmation unavailable: RESEND_API_KEY missing')
      } else {
        const message = 'Ahoj,\\n\\nděkujeme, že jste napsal/a na Opravao.cz. Vaši zprávu jsme přijali a co nejdříve se vám ozveme.\\n\\nTým Opravao.cz'
        const bannerBase64 = ''
        const html = '<div style="font-family:Arial,Helvetica,sans-serif;color:#20211f;line-height:1.6;max-width:680px;margin:0 auto"><img src="cid:opravao-banner" alt="Opravao.cz — Dáme to do pořádku" width="600" style="display:block;width:100%;max-width:600px;height:auto;border:0;margin:0 0 24px"><p>Ahoj,</p><p>děkujeme, že jste napsal/a na Opravao.cz. Vaši zprávu jsme přijali a co nejdříve se vám ozveme.</p><p>Tým Opravao.cz</p></div>'
        try {
          const mailResponse = await fetch('https://api.resend.com/emails', {
            method: 'POST',
            headers: {
              'Authorization': 'Bearer ' + resendKey,
              'Content-Type': 'application/json',
              'Idempotency-Key': 'opravao-auto-confirmation-' + data.id,
            },
            body: JSON.stringify({
              from: 'Opravao.cz <odpovedi@opravao.cz>',
              to: [email],
              reply_to: 'info@opravao.cz',
              subject: 'Potvrzení přijetí zprávy – Opravao.cz',
              text: message,
              html,
              attachments: [{ filename: 'opravao-banner.jpg', content: bannerBase64, content_type: 'image/jpeg', content_id: 'opravao-banner' }],
            }),
          })
          let mailData: Record<string, unknown> = {}
          try { mailData = await mailResponse.json() } catch {}
          if (mailResponse.ok) {
            confirmationSent = true
            const { error: communicationError } = await ctx.supabaseAdmin.from('plotao_leads').update({
              communication: [{
                direction: 'out',
                channel: 'email',
                body: message,
                sent_at: new Date().toISOString(),
                provider: 'resend',
                provider_id: typeof mailData.id === 'string' ? mailData.id : null,
                kind: 'automatic_confirmation',
              }],
            }).eq('id', data.id).eq('source', 'opravao.cz')
            if (communicationError) console.error('opravao confirmation log failed', communicationError.code || 'unknown')
          } else {
            console.error('opravao customer confirmation rejected', mailResponse.status, typeof mailData.name === 'string' ? mailData.name : '')
          }
        } catch (error) {
          console.error('opravao customer confirmation network failure', error instanceof Error ? error.message : 'unknown')
        }
      }
      return respond(201, { ok: true, received_at: receivedAt, confirmation_sent: confirmationSent, offers_created: offersCreated, offer_emails_sent: offerEmailsSent, distribution_status: distributionStatus }, origin)
    },
  ),
}
